// One bar chart from the sheet: the "label" column names a bar, "value" sets its height.
// The title comes from chartTitle in Settings.
const TITLE = $('Settings').first().json.chartTitle;
const rows = $input.all().map((item) => item.json);
if (!rows.length) throw new Error('The sheet needs a label column and a numeric value column.');
// Number('') and Number(null) are 0, so an empty cell has to be caught before Number().
const bad = (v) => v == null || String(v).trim() === '' || Number.isNaN(Number(v));
const badRow = rows.findIndex((row) => bad(row.value));
if (badRow !== -1) {
  throw new Error('Row ' + (badRow + 1) + ' of the sheet (label "' + rows[badRow].label + '") has no number in the value column. The sheet needs a label column and a numeric value column.');
}
const labels = rows.map((row) => String(row.label));
const values = rows.map((row) => Number(row.value));
const chart = {
  type: 'bar',
  data: { labels, datasets: [{ label: TITLE, data: values }] },
  options: { plugins: { legend: { display: false }, title: { display: true, text: TITLE }, chartpng: { source: 'Source: Google Sheets' } } },
};
const imageUrl = 'https://chartpng.dev/chart?w=800&h=450&dpr=2&c=' + encodeURIComponent(JSON.stringify(chart));
const caption = TITLE + ': ' + values.at(-1) + ' in ' + labels.at(-1);
// Slack refuses an image block whose URL is longer than 3000 characters. Telegram has no such limit and does not read
// blocks or slackError; the Post to Slack node stops with slackError, so Slack never gets a broken message.
const blocks = [{ type: 'image', image_url: imageUrl, alt_text: caption }];
const slackError = imageUrl.length > 3000
  ? 'The chart URL is ' + imageUrl.length + ' characters and Slack takes at most 3000 in an image block. Use fewer rows or shorter labels. Telegram is not affected.'
  : '';
return [{ json: { imageUrl, caption, blocks, slackError } }];
